import CoreGraphics
import Foundation
import NVRCore
import Testing

/// The names of saved pictures and the region math (docs/CAPTURE.md "Save
/// picture"). The naming vectors are `fixtures/synthetic/capture-names.json`,
/// generated by the Rust rules (`crates/capture/tests/name_vectors.rs`),
/// which the Windows tests read too.
@Suite struct PictureNamingTests {
    private static func vectors() throws -> [String: Any] {
        let data = try Data(contentsOf: Fixtures.directory.appendingPathComponent("capture-names.json"))
        return try #require(try JSONSerialization.jsonObject(with: data) as? [String: Any])
    }

    @Test func constantsMatchTheVectors() throws {
        let v = try Self.vectors()
        #expect(v["maxNameChars"] as? Int == PictureNaming.maxNameChars)
        #expect(v["shareSafeLabel"] as? String == PictureNaming.shareSafeLabel)
    }

    @Test func sanitizeVectors() throws {
        let cases = try #require(try Self.vectors()["sanitize"] as? [[String: Any]])
        #expect(cases.count >= 8)
        for c in cases {
            let input = try #require(c["input"] as? String)
            #expect(PictureNaming.sanitize(input) == c["expected"] as? String, "\(input.prefix(20))")
        }
    }

    @Test func pictureNameVectors() throws {
        let cases = try #require(try Self.vectors()["picture"] as? [[String: Any]])
        #expect(cases.count >= 10)
        for c in cases {
            let ms = try #require((c["ms"] as? NSNumber)?.int64Value)
            let raw = try #require(c["format"] as? String)
            let format = try #require(PictureFormat(rawValue: raw))
            let takenNames = try #require(c["taken"] as? [String])
            let taken = Set(takenNames)
            let camera = try #require(c["camera"] as? String)
            let name = PictureNaming.fileName(
                localMillis: ms, camera: camera, shareSafe: c["shareSafe"] as? Bool == true,
                format: format, taken: { taken.contains($0) })
            #expect(name == c["expected"] as? String, "\(ms)")
        }
    }

    @Test func aLocalTimeBecomesTheWallClockStamp() {
        var calendar = Calendar(identifier: .gregorian)
        let zone = TimeZone(identifier: "America/Los_Angeles")!
        calendar.timeZone = zone
        let date = calendar.date(from: DateComponents(year: 2026, month: 10, day: 11, hour: 17, minute: 2, second: 3))!
            .addingTimeInterval(0.25)
        #expect(PictureNaming.stamp(localMillis: PictureNaming.localMillis(date, in: zone)) == "2026-10-11 17.02.03.250")
    }

    @Test func extensionsMapToFormats() {
        #expect(PictureFormat(extension: "JPG") == .jpeg && PictureFormat(extension: "png") == .png)
        #expect(PictureFormat(extension: "gif") == nil)
        #expect(PictureFormat.jpeg.fileExtension == "jpg")
    }

    // MARK: Region

    private let wide = CGSize(width: 1920, height: 1080)

    @Test func theWholePictureAtOneTimes() {
        let r = PictureRegion.visible(
            layoutSize: wide, offset: .zero, tile: CGSize(width: 640, height: 360), fill: false, zoom: .none)
        #expect(r == PixelRegion(x: 0, y: 0, width: 1920, height: 1080))
    }

    @Test func aBufferWithPaddingKeepsItsOffset() {
        let whole = PictureRegion.visible(
            layoutSize: wide, offset: CGPoint(x: 0, y: 0), tile: CGSize(width: 500, height: 500), fill: false, zoom: .none)
        #expect(whole?.size == wide)
        let shifted = PictureRegion.visible(
            layoutSize: CGSize(width: 100, height: 50), offset: CGPoint(x: 8, y: 4), tile: CGSize(width: 200, height: 100),
            fill: false, zoom: TileZoom(scale: 2, center: CGPoint(x: 0.5, y: 0.5)))
        #expect(shifted == PixelRegion(x: 33, y: 17, width: 50, height: 25))
    }

    @Test func twoTimesCenteredIsTheMiddleHalf() {
        let r = PictureRegion.visible(
            layoutSize: wide, offset: .zero, tile: CGSize(width: 640, height: 360), fill: false,
            zoom: TileZoom(scale: 2, center: CGPoint(x: 0.5, y: 0.5)))
        #expect(r == PixelRegion(x: 480, y: 270, width: 960, height: 540))
    }

    @Test func aCornerIsClampedInsideThePicture() {
        let r = PictureRegion.visible(
            layoutSize: wide, offset: .zero, tile: CGSize(width: 640, height: 360), fill: false,
            zoom: TileZoom(scale: 4, center: CGPoint(x: 1, y: 1)))
        #expect(r == PixelRegion(x: 1440, y: 810, width: 480, height: 270))
    }

    @Test func zoomingNeverEnlarges() {
        for scale in [1.5, 3.0, 8.0] {
            let r = PictureRegion.visible(
                layoutSize: wide, offset: .zero, tile: CGSize(width: 300, height: 700), fill: false,
                zoom: TileZoom(scale: scale, center: CGPoint(x: 0.3, y: 0.6)))
            #expect(r.map { $0.width <= 1920 && $0.height <= 1080 && $0.x >= 0 && $0.y >= 0 && $0.x + $0.width <= 1920 && $0.y + $0.height <= 1080 } == true)
        }
    }

    @Test func aFilledTileCropsToItsShape() {
        // A 16:9 picture filling a square tile shows its middle 1080 x 1080.
        let r = PictureRegion.visible(
            layoutSize: wide, offset: .zero, tile: CGSize(width: 400, height: 400), fill: true, zoom: .none)
        #expect(r == PixelRegion(x: 420, y: 0, width: 1080, height: 1080))
    }

    @Test func noPictureNoRegion() {
        #expect(PictureRegion.visible(layoutSize: .zero, offset: .zero, tile: CGSize(width: 10, height: 10), fill: false, zoom: .none) == nil)
    }
}
